-- US round 2: Iowa State, Kansas State, Oregon State, Delaware, Nebraska-Lincoln, Washington State, Michigan Tech.
-- Each row comes from the school's own page, read on 1 Nov 2026. All rows stay verified = false. Safe to run more than once.
-- Read but nothing usable: Kentucky and Auburn (pages name no international award). Not found: Stony Brook, Buffalo.
drop table if exists pg_temp._us2;
create temp table _us2 (school_id uuid, name text, funding_type text, deadline date, link text, criteria text, award_note text);

insert into _us2 values
('f3cd6b0e-2422-47ea-9844-d7215cf620f3', 'Iowa State President''s International Student Excellence Award', 'Partial', null, 'https://iastate.edu/admission-and-aid/admissions/international-admissions/international-student-excellence-award',
 $q$Who is eligible: Incoming first-year international students who are offered admission and charged international tuition. Requirements: Based on your high school GPA and an SAT or ACT score, which is required for this award. You must study at least 12 credits each semester, summer excluded. The award covers undergraduate tuition and fees only and cannot be combined with another Excellence Award or the International Merit Scholarship. To renew it you need a cumulative GPA of at least 3.0. How to apply: No application. It is awarded automatically when you are admitted. Accept your offer by 1 May for fall or 15 December for spring.$q$,
 $q$USD 14,000 a year, USD 56,000 in total, for up to 8 semesters.$q$),
('f3cd6b0e-2422-47ea-9844-d7215cf620f3', 'Iowa State Dean''s International Student Excellence Award', 'Partial', null, 'https://iastate.edu/admission-and-aid/admissions/international-admissions/international-student-excellence-award',
 $q$Who is eligible: Incoming first-year international students who are offered admission and charged international tuition. Requirements: Based on your high school GPA and an SAT or ACT score, which is required for this award. You must study at least 12 credits each semester. It cannot be combined with another Excellence Award or the International Merit Scholarship. To renew it you need a cumulative GPA of at least 2.5. How to apply: No application. It is awarded automatically when you are admitted. Accept your offer by 1 May for fall or 15 December for spring.$q$,
 $q$USD 12,000 a year, USD 48,000 in total, for up to 8 semesters.$q$),
