('d485275a-649b-48c3-bb1f-e352c3ecbd97', 'Oregon State Regional Award', 'Partial', null, 'https://admissions.oregonstate.edu/international-admissions/prices-scholarships/scholarships-international-students/undergraduate',
 $q$Who is eligible: International undergraduate applicants, with the amount set by your country of residence. Africa is listed in the Central Asia, Africa and Vietnam group. Requirements: Students on government or other external sponsorship are not eligible. Renewable while you stay in good academic standing with a GPA of 2.0 or higher. How to apply: No application. Qualified applicants are awarded with their offer. The page lists no deadline, so contact your INTO regional office or OSU representative. The page says awards are limited and may be lower than published.$q$,
 $q$The Central Asia, Africa and Vietnam group is listed at USD 12,000 a year, USD 48,000 over four years. The page also shows Central Asia at USD 16,000 a year with the same total, which does not add up, so confirm the figure with the school.$q$),
('d485275a-649b-48c3-bb1f-e352c3ecbd97', 'Oregon State Provost''s Scholarship for Excellence', 'Partial', null, 'https://admissions.oregonstate.edu/international-admissions/prices-scholarships/scholarships-international-students/undergraduate',
 $q$Who is eligible: First-year and international year-one students with a GPA of 3.5 or higher, or the equivalent. Requirements: Renewal needs a GPA of 3.0 or higher. It cannot be combined with a Regional Award. How to apply: No application. It is awarded automatically.$q$,
 $q$USD 6,000 a year for up to 4 years.$q$),
('d485275a-649b-48c3-bb1f-e352c3ecbd97', 'Oregon State Honorary Scholarship for Leadership', 'Partial', null, 'https://admissions.oregonstate.edu/international-admissions/prices-scholarships/scholarships-international-students/undergraduate',
 $q$Who is eligible: International students with a GPA of at least 3.0 who show merit and leadership. Requirements: It can be combined with every OSU scholarship except Regional Awards. How to apply: You must apply. Contact the admissions office at the email listed on the page. The page gives no deadline.$q$,
 $q$USD 2,000, paid once in your first year or term.$q$),
('47d60e3c-2296-438d-8597-0c408fb82169', 'University of Delaware International Merit Scholarship', 'Partial', null, 'https://www.udel.edu/apply/undergraduate-admissions/financing-your-degree/international-students/',
 $q$Who is eligible: First-year international students who apply. Requirements: The page gives no other criteria and says scholarships are subject to availability. How to apply: No application. All first-year international applicants are considered automatically. Deadline: The page lists none. The university does not offer need-based aid to international students.$q$,
 $q$USD 10,000 to USD 15,000 a year.$q$),
('47d60e3c-2296-438d-8597-0c408fb82169', 'University of Delaware Distinguished Scholars Award', 'Full', null, 'https://www.udel.edu/apply/undergraduate-admissions/financing-your-degree/international-students/',
 $q$Who is eligible: First-year international students who apply. It is the most prestigious award. Requirements: Keep a 3.0 GPA at Delaware. The page gives no other criteria. How to apply: No application. All first-year international applicants are considered automatically. Deadline: The page lists none.$q$,
 $q$Can cover tuition and room and board for four years. The page gives no amount.$q$),
('0e04aec7-ced7-4e08-bbf7-13e68101f68b', 'Nebraska Global Ambassador Tuition Scholarship', 'Partial', null, 'https://admissions.unl.edu/cost/scholarships/global-ambassador-scholarship/',
 $q$Who is eligible: First-year, international and transfer students with outstanding academic achievement who meet the English requirement for unconditional admission. Requirements: No minimum admission GPA or test score is stated. To renew you need a cumulative GPA of at least 2.0 and 24 completed credit hours each year. The page also says recipients must be U.S. citizens or verified qualified aliens, which seems to conflict with an award for international students. Ask the admissions office before you rely on it. How to apply: No separate application. All international admits are evaluated for Global Scholarships. Pay your enrolment deposit in MyRED by 15 May. English deadlines are 15 July for fall and 1 December for spring.$q$,
 $q$USD 10,000 a year toward international tuition, up to USD 40,000 over four years.$q$),
('6d40b3f9-222e-4962-8cec-6d2a90faab42', 'WSU International Academic Award', 'Partial', null, 'https://financialaid.wsu.edu/nonresident-scholarships',
 $q$Who is eligible: International students offered admission to WSU Pullman. Requirements: Level 1 needs a GPA of 3.60 or higher. Level 2 needs a GPA of 3.0 to 3.59. To renew you need a cumulative GPA of 3.0 by the end of spring, 12 credits a semester and non-resident degree-seeking status. How to apply: No application. International Programs awards it automatically to qualifying admitted students.$q$,
 $q$A tuition waiver of USD 4,000 (Level 1) or USD 2,000 (Level 2).$q$),
('f56e9b96-d338-4ee8-b81e-7d2b973a8e97', 'Michigan Tech FIRST Scholarship', 'Partial', '2027-02-01', 'https://www.mtu.edu/admissions/first/',
 $q$Who is eligible: Incoming first-year students in any major who competed on a FIRST Robotics Competition, FIRST Tech Challenge or VEX Robotics team in high school. International students are welcome to apply. Requirements: No test scores are needed. It can be combined with merit-based scholarships. How to apply: You must apply. Submit the Michigan Tech Scholarship Application, apply for admission, and send your official transcripts. Deadline: 1 February, 11:59 pm Eastern, for the scholarship and the admission application. Applicants are told in March.$q$,
 $q$25 awards of USD 4,000 a year and 15 awards of USD 1,500 a year, renewable for four years.$q$);

insert into public.scholarships (name, funder, country, funding_type, level, criteria, award_note, link, source_url, school_id, deadline, verified, demo)
select n.name, s.name, 'United States', n.funding_type, 'Undergraduate', n.criteria, n.award_note, n.link, n.link, n.school_id, n.deadline, false, false
from _us2 n join public.schools s on s.id = n.school_id
where not exists (select 1 from public.scholarships x where x.name = n.name and x.school_id = n.school_id);

select s.name as school, count(*) as scholarships from public.scholarships x join public.schools s on s.id = x.school_id where x.name in (select name from _us2) group by s.name order by 1;
